10	class UploadBrandLogoRequest extends BaseFormRequest
11	{
12	    public function rules(): array
13	    {
14	        return [
15	            'logo' => [
16	                'required',
17	                'file',
18	                'mimes:jpeg,jpg,png,webp',
19	                'max:5120',
20	            ],
21	            'variant' => ['sometimes', 'string', Rule::in(['full', 'square'])],
22	        ];
23	    }
24	
25	    public function messages(): array
26	    {
27	        return [
28	            'logo.mimes' => 'Brand logo must be a JPEG, PNG, or WebP image.',
29	            'logo.max' => 'Brand logo must be smaller than 5 MB.',
30	            'variant.in' => 'Logo variant must be one of: full, square.',
31	        ];
32	    }
33	}
