1	<?php
2	
3	namespace App\Services\Media;
4	
5	use App\Jobs\ProcessImageVariantsJob;
6	use App\Models\Core\Site\Site;
7	use App\Models\Core\Site\SiteMedia;
8	use App\Services\Cache\SiteCacheService;
9	use Illuminate\Http\UploadedFile;
10	use Illuminate\Support\Facades\DB;
11	use Illuminate\Support\Facades\Log;
12	use Illuminate\Support\Facades\Storage;
13	use Throwable;
14	
15	// V2: Single seam for brand design media — logo (full + square) and
16	// placeholders. Both ProfessionalUploadController (multipart) and
17	// SyncShopifyBrandDesignJob (Shopify-fetched bytes) call into this service so
18	// every brand design asset goes through the same persistence + variant pipeline.
19	class BrandDesignMediaService
20	{
21	    public const PLACEHOLDER_MAX = 5;
22	
23	    private const ALLOWED_IMAGE_MIMES = ['image/jpeg', 'image/png', 'image/webp'];
24	
25	    public function __construct(
26	        private readonly ImageVariantService $images,
27	    ) {}
28	
29	    /**
30	     * Upload a logo from a multipart UploadedFile. Variant is 'full' or 'square'.
31	     * Soft-deletes any prior active row with the same purpose so the singleton
32	     * index holds.
33	     */
34	    public function upsertLogoFromUploadedFile(Site $site, string $proId, UploadedFile $file, string $variant): SiteMedia
35	    {
36	        $purpose = $this->purposeForLogoVariant($variant);
37	
38	        // finfo against actual bytes — getMimeType() trusts the client Content-Type header.
39	        $this->assertMimeAllowed((new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath()));
40	
41	        $media = $this->createDesignRow($site, $purpose, $file->getMimeType(), $file->getSize(), 0);
42	
43	        $basePath = "images/{$proId}/{$media->id}";
44	
45	        try {
46	            $originalPath = $this->images->storeOriginal($file, $basePath);
47	        } catch (Throwable $e) {
48	            Log::error('BrandDesignMediaService: failed to store logo original.', [
49	                'site_id' => $site->id,
50	                'purpose' => $purpose,
51	                'error' => $e->getMessage(),
52	            ]);
53	            $media->delete();
54	            throw $e;
55	        }
56	
57	        $media->update(['path' => $originalPath]);
58	        $this->dispatchVariantJob($media->id, $originalPath, $basePath);
59	        $this->invalidateSiteCache($site);
60	
61	        return $media->refresh();
62	    }
63	
64	    /**
65	     * Upload a logo from raw bytes already in memory (Shopify CDN download path).
66	     * Same singleton-replace semantics as upsertLogoFromUploadedFile.
67	     */
68	    public function upsertLogoFromBytes(Site $site, string $proId, string $bytes, string $mime, string $variant): SiteMedia
69	    {
70	        $purpose = $this->purposeForLogoVariant($variant);
71	
72	        // finfo against actual bytes — $mime comes from Shopify CDN headers, not verified.
73	        $this->assertMimeAllowed((new \finfo(FILEINFO_MIME_TYPE))->buffer($bytes));
74	
75	        $media = $this->createDesignRow($site, $purpose, $mime, strlen($bytes), 0);
76	
77	        $basePath = "images/{$proId}/{$media->id}";
78	        $ext = $this->extensionFromMime($mime);
79	        $hash = substr(hash('sha256', $bytes), 0, 16);
80	        $originalPath = "{$basePath}/original_{$hash}.{$ext}";
81	
82	        try {
83	            Storage::disk($this->images->resolvedDiskName())->put($originalPath, $bytes, 'public');
84	        } catch (Throwable $e) {
85	            Log::error('BrandDesignMediaService: failed to store logo bytes.', [
86	                'site_id' => $site->id,
87	                'purpose' => $purpose,
88	                'error' => $e->getMessage(),
89	            ]);
90	            $media->delete();
91	            throw $e;
92	        }
93	
94	        $media->update(['path' => $originalPath]);
95	        $this->dispatchVariantJob($media->id, $originalPath, $basePath);
96	        $this->invalidateSiteCache($site);
97	
98	        return $media->refresh();
99	    }
100	
101	    /**
102	     * Append a placeholder image. Throws PlaceholderLimitExceededException if
103	     * 5 active placeholders already exist for the site.
104	     */
105	    public function addPlaceholder(Site $site, string $proId, UploadedFile $file): SiteMedia
106	    {
107	        $this->assertMimeAllowed((new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath()));
108	
109	        $media = DB::transaction(function () use ($site, $file) {
110	            $activeCount = SiteMedia::query()
111	                ->where('site_id', $site->id)
112	                ->where('pool', SiteMedia::POOL_DESIGN)
113	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
114	                ->whereNull('deleted_at')
115	                ->count();
116	
117	            if ($activeCount >= self::PLACEHOLDER_MAX) {
118	                throw new PlaceholderLimitExceededException(self::PLACEHOLDER_MAX);
119	            }
120	
121	            $maxSort = SiteMedia::query()
122	                ->where('site_id', $site->id)
123	                ->where('pool', SiteMedia::POOL_DESIGN)
124	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
125	                ->whereNull('deleted_at')
126	                ->max('sort_order');
127	
128	            return SiteMedia::create([
129	                'site_id' => $site->id,
130	                'pool' => SiteMedia::POOL_DESIGN,
131	                'purpose' => SiteMedia::PURPOSE_PLACEHOLDER,
132	                'path' => '',
133	                'alt_text' => $file->getClientOriginalName(),
134	                'sort_order' => is_null($maxSort) ? 0 : ((int) $maxSort + 1),
135	                'is_active' => true,
136	                'media_type' => SiteMedia::MEDIA_TYPE_IMAGE,
137	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
138	                'original_mime' => $file->getMimeType(),
139	                'original_size_bytes' => $file->getSize(),
140	            ]);
141	        });
142	
143	        $basePath = "images/{$proId}/{$media->id}";
144	
145	        try {
146	            $originalPath = $this->images->storeOriginal($file, $basePath);
147	        } catch (Throwable $e) {
148	            Log::error('BrandDesignMediaService: failed to store placeholder original.', [
149	                'site_id' => $site->id,
150	                'media_id' => $media->id,
151	                'error' => $e->getMessage(),
152	            ]);
153	            $media->delete();
154	            throw $e;
155	        }
156	
157	        $media->update(['path' => $originalPath]);
158	        $this->dispatchVariantJob($media->id, $originalPath, $basePath);
159	        $this->invalidateSiteCache($site);
