164	    /**
165	     * Soft-delete a placeholder and repack the remaining sort_order so the list
166	     * has no gaps. Throws if the media id doesn't belong to this site / isn't a
167	     * placeholder.
168	     */
169	    public function deletePlaceholder(Site $site, string $mediaId): void
170	    {
171	        DB::transaction(function () use ($site, $mediaId) {
172	            $row = SiteMedia::query()
173	                ->where('id', $mediaId)
174	                ->where('site_id', $site->id)
175	                ->where('pool', SiteMedia::POOL_DESIGN)
176	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
177	                ->whereNull('deleted_at')
178	                ->lockForUpdate()
179	                ->first();
180	
181	            if (! $row) {
182	                abort(404, 'Placeholder not found.');
183	            }
184	
185	            $row->delete();
186	
187	            // Re-pack remaining placeholders to (0, 1, 2, ...) — first push to
188	            // a high offset to avoid colliding with the partial unique index,
189	            // then assign final values.
190	            $remaining = SiteMedia::query()
191	                ->where('site_id', $site->id)
192	                ->where('pool', SiteMedia::POOL_DESIGN)
193	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
194	                ->whereNull('deleted_at')
195	                ->orderBy('sort_order')
196	                ->lockForUpdate()
197	                ->get();
198	
199	            $offset = self::PLACEHOLDER_MAX + 1000;
200	            foreach ($remaining as $idx => $r) {
201	                SiteMedia::query()->where('id', $r->id)->update(['sort_order' => $offset + $idx]);
202	            }
203	            foreach ($remaining as $idx => $r) {
204	                SiteMedia::query()->where('id', $r->id)->update(['sort_order' => $idx]);
205	            }
206	        });
207	
208	        $this->invalidateSiteCache($site);
209	    }
