211	    /**
212	     * Replace the existing sort_order of placeholders with the supplied ordering.
213	     * The id list must contain exactly the active placeholder ids for this site
214	     * (no extras, no missing rows). Two-pass update to avoid index collisions.
215	     */
216	    public function reorderPlaceholders(Site $site, array $orderedIds): void
217	    {
218	        DB::transaction(function () use ($site, $orderedIds) {
219	            $existing = SiteMedia::query()
220	                ->where('site_id', $site->id)
221	                ->where('pool', SiteMedia::POOL_DESIGN)
222	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
223	                ->whereNull('deleted_at')
224	                ->lockForUpdate()
225	                ->pluck('id')
226	                ->all();
227	
228	            $existingSet = array_flip($existing);
229	            $orderedSet = array_flip($orderedIds);
230	
231	            if (count($orderedIds) !== count($existing) || array_diff_key($existingSet, $orderedSet) !== []) {
232	                abort(422, 'Reorder ids must match active placeholders exactly.');
233	            }
234	
235	            $offset = self::PLACEHOLDER_MAX + 1000;
236	            foreach ($orderedIds as $idx => $id) {
237	                SiteMedia::query()->where('id', $id)->update(['sort_order' => $offset + $idx]);
238	            }
239	            foreach ($orderedIds as $idx => $id) {
240	                SiteMedia::query()->where('id', $id)->update(['sort_order' => $idx]);
241	            }
242	        });
243	
244	        $this->invalidateSiteCache($site);
245	    }
