271	    /**
272	     * Resolve all brand design media for a site into the shape that every reader
273	     * (HydrogenBrandDesignController, BrandDesignController, SiteCacheService)
274	     * consumes. Only ready rows are returned — pending/failed rows are skipped.
275	     *
276	     * @return array{
277	     *     logo: array{full_url: ?string, square_url: ?string},
278	     *     placeholders: array<int, array{id: string, alt_text: ?string, url: string, sort_order: int}>
279	     * }
280	     */
281	    public function listDesignMedia(string $siteId): array
282	    {
283	        $rows = SiteMedia::query()
284	            ->where('site_id', $siteId)
285	            ->where('pool', SiteMedia::POOL_DESIGN)
286	            ->whereNull('deleted_at')
287	            ->where('is_active', true)
288	            ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
289	            ->with('mediaVariants')
290	            ->orderBy('sort_order')
291	            ->get();
292	
293	        $logo = ['full_url' => null, 'square_url' => null];
294	        $placeholders = [];
295	
296	        foreach ($rows as $row) {
297	            $url = $row->variantUrls()['optimized'] ?? null;
298	            if ($url === null) {
299	                continue;
300	            }
301	
302	            if ($row->purpose === SiteMedia::PURPOSE_LOGO_FULL) {
303	                $logo['full_url'] = $url;
304	            } elseif ($row->purpose === SiteMedia::PURPOSE_LOGO_SQUARE) {
305	                $logo['square_url'] = $url;
306	            } elseif ($row->purpose === SiteMedia::PURPOSE_PLACEHOLDER) {
307	                $placeholders[] = [
308	                    'id' => $row->id,
309	                    'alt_text' => $row->alt_text,
310	                    'url' => $url,
311	                    'sort_order' => (int) $row->sort_order,
312	                ];
313	            }
314	        }
315	
316	        return ['logo' => $logo, 'placeholders' => $placeholders];
317	    }
