358	                'path' => '',
359	                'sort_order' => $sortOrder,
360	                'is_active' => true,
361	                'media_type' => SiteMedia::MEDIA_TYPE_IMAGE,
362	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
