369	    private function dispatchVariantJob(string $imageId, string $originalPath, string $basePath): void
370	    {
371	        $queueDefault = (string) config('queue.default', 'sync');
372	        $processInline = in_array(app()->environment(), ['local', 'testing'], true)
373	            || $queueDefault === 'sync';
374	
375	        if ($processInline) {
376	            try {
377	                ProcessImageVariantsJob::dispatchSync(
378	                    originalPath: $originalPath,
379	                    imageId: $imageId,
380	                    basePath: $basePath,
381	                );
382	            } catch (Throwable $e) {
383	                Log::error('BrandDesignMediaService: inline variant processing failed.', [
384	                    'image_id' => $imageId,
385	                    'error' => $e->getMessage(),
386	                ]);
387	            }
388	
389	            return;
390	        }
391	
392	        try {
393	            ProcessImageVariantsJob::dispatch(
394	                originalPath: $originalPath,
395	                imageId: $imageId,
396	                basePath: $basePath,
397	            );
398	        } catch (Throwable $e) {
399	            Log::error('BrandDesignMediaService: queue dispatch failed; falling back to sync.', [
400	                'image_id' => $imageId,
401	                'error' => $e->getMessage(),
402	            ]);
403	            try {
404	                ProcessImageVariantsJob::dispatchSync(
405	                    originalPath: $originalPath,
406	                    imageId: $imageId,
407	                    basePath: $basePath,
408	                );
409	            } catch (Throwable $sync) {
410	                Log::error('BrandDesignMediaService: sync fallback also failed.', [
411	                    'image_id' => $imageId,
412	                    'error' => $sync->getMessage(),
413	                ]);
414	            }
415	        }
416	    }
