419	    {
420	        try {
421	            $siteCache = app(SiteCacheService::class);
422	            $siteCache->invalidateSite($site);
423	            // Also bust the Hydrogen brand-design cache so dashboard saves
424	            // (logo, placeholder upload/delete/reorder) surface on Hydrogen
425	            // inside its 5s staleWhileRevalidate window.
426	            $siteCache->forgetBrandDesign((string) $site->id);
