436	    {
437	        return match (strtolower(trim(explode(';', $mime)[0] ?? ''))) {
438	            'image/png' => 'png',
439	            'image/jpeg', 'image/jpg' => 'jpg',
440	            'image/webp' => 'webp',
441	            'image/gif' => 'gif',
442	            default => 'png',
