275	    private function diskName(): string
276	    {
277	        $configured = (string) config('sidest.media_disk', 'media');
278	
279	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
280	        // but injects platform env vars directly into the process environment at runtime,
281	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
282	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
283	        if (is_string($explicit) && trim($explicit) !== '') {
284	            return $configured;
285	        }
286	
287	        // Laravel Cloud injects disks dynamically and may set a non-"media"
288	        // filesystems.default disk. If media disk is only a fallback value,
289	        // prefer the Cloud default to avoid missing/empty media credentials.
290	        if ($configured === 'media') {
291	            $default = (string) config('filesystems.default', 'local');
292	            $defaultConfig = config("filesystems.disks.{$default}");
293	
294	            if (
295	                $default !== '' &&
296	                $default !== 'local' &&
297	                $default !== 'media' &&
298	                is_array($defaultConfig) &&
299	                (($defaultConfig['driver'] ?? null) === 's3')
300	            ) {
301	                Log::warning('SIDEST_MEDIA_DISK not set; using filesystems.default disk for media operations.', [
302	                    'configured_media_disk' => $configured,
303	                    'fallback_disk' => $default,
304	                ]);
305	
306	                return $default;
307	            }
308	        }
309	
310	        return $configured;
311	    }
