352	     * Load an image file into a GD resource regardless of source format.
353	     *
354	     * Refuses images whose pixel count exceeds sidest.image_max_pixels by
355	     * throwing UnprocessableImageException BEFORE any bitmap memory is
356	     * allocated. This is the defense against image-bomb uploads — a tiny
357	     * JPEG/PNG file can decode to a huge bitmap (4 bytes per pixel), which
358	     * the worker cannot survive even with the canvas caps applied.
359	     *
360	     * The getimagesize() call reads only the file header (a few KB), not
361	     * the pixel data, so the guard is effectively free.
362	     */
363	    private function loadImage(string $path): \GdImage|false
364	    {
365	        // Sniff actual bytes before getimagesize — prevents a crafted file from
366	        // claiming a safe format while hiding a decompression bomb in its content stream.
367	        $actualMime = (new \finfo(FILEINFO_MIME_TYPE))->file($path);
368	        if (! in_array($actualMime, self::ALLOWED_IMAGE_MIMES, true)) {
369	            throw new UnprocessableImageException(
370	                "Rejected: MIME type '{$actualMime}' is not an accepted image format."
371	            );
372	        }
373	
374	        $info = @getimagesize($path);
375	        if (! $info) {
376	            return false;
377	        }
378	
379	        $width = (int) $info[0];
380	        $height = (int) $info[1];
381	        $maxPixels = (int) config('sidest.image_max_pixels', 24_000_000);
382	
383	        if ($width * $height > $maxPixels) {
384	            throw new UnprocessableImageException(sprintf(
385	                'Image dimensions exceed safe processing limit (%d x %d = %d pixels, max %d).',
386	                $width,
387	                $height,
388	                $width * $height,
389	                $maxPixels,
390	            ));
