393	        return match ($info[2]) {
394	            IMAGETYPE_JPEG => @imagecreatefromjpeg($path),
395	            IMAGETYPE_PNG => @imagecreatefrompng($path),
396	            IMAGETYPE_WEBP => @imagecreatefromwebp($path),
