424	    private function encodeWebpToTargetSize(
425	        \GdImage $image,
426	        string $tmpFile,
427	        int $maxQuality,
428	        int $minQuality,
429	        int $targetBytes,
430	    ): int {
431	        $lower = max(1, min(100, $minQuality));
432	        $upper = max($lower, min(100, $maxQuality));
433	
434	        $bestQuality = null;
435	
436	        while ($lower <= $upper) {
437	            $mid = intdiv($lower + $upper, 2);
438	            $size = $this->encodeWebp($image, $tmpFile, $mid);
439	
440	            if ($size <= $targetBytes) {
441	                $bestQuality = $mid;
442	                $lower = $mid + 1;
443	
444	                continue;
445	            }
446	
447	            $upper = $mid - 1;
