466	     */
467	    private function calculateDimensions(
468	        int $srcW, int $srcH,
469	        int $maxW, int $maxH,
470	        string $fit,
471	    ): array {
472	        if ($fit === 'cover') {
473	            $srcRatio = $srcW / $srcH;
474	            $dstRatio = $maxW / $maxH;
475	
476	            if ($srcRatio > $dstRatio) {
477	                $cropH = $srcH;
478	                $cropW = (int) round($srcH * $dstRatio);
479	                $cropX = (int) round(($srcW - $cropW) / 2);
480	                $cropY = 0;
481	            } else {
482	                $cropW = $srcW;
483	                $cropH = (int) round($srcW / $dstRatio);
484	                $cropX = 0;
485	                $cropY = (int) round(($srcH - $cropH) / 2);
486	            }
487	
488	            return [$cropX, $cropY, $cropW, $cropH, $maxW, $maxH];
489	        }
490	
491	        // "inside" – fit within bounds, no crop, never upscale
492	        $ratio = min($maxW / $srcW, $maxH / $srcH, 1);
493	        $dstW = (int) round($srcW * $ratio);
494	        $dstH = (int) round($srcH * $ratio);
495	
496	        return [0, 0, $srcW, $srcH, $dstW, $dstH];
497	    }
