9	// V2: Validates image or video upload to a pool — enforces one-of constraint, file type/size limits, and video feature flag check.
10	class UploadImageRequest extends BaseFormRequest
11	{
12	    public function rules(): array
13	    {
14	        $imageMaxKb = (int) config('sidest.image_max_upload_size', 10240);
15	        $videoMaxKb = (int) config('sidest.video_max_upload_size', 512000);
16	
17	        return [
18	            'pool' => [
19	                'required',
20	                'string',
21	                Rule::in(config('sidest.upload_pools')),
22	            ],
23	            // Either `image` or `video` must be provided (not both). The after-validator
24	            // enforces the one-of constraint; individual rules run only when the field exists.
25	            'image' => [
26	                'sometimes',
27	                'nullable',
28	                'file',
29	                'image',
30	                'mimes:jpeg,png,webp',
31	                "max:{$imageMaxKb}",
32	            ],
33	            'video' => [
34	                'sometimes',
35	                'nullable',
36	                'file',
37	                'mimes:mp4,mov,webm,avi',
38	                "max:{$videoMaxKb}",
39	            ],
40	            'alt_text' => ['sometimes', 'nullable', 'string', 'max:255'],
41	            'caption' => ['sometimes', 'nullable', 'string', 'max:200'],
42	        ];
43	    }
44	
45	    protected function withValidator(Validator $validator): void
46	    {
47	        $validator->after(function (Validator $v) {
48	            $hasImage = $this->hasFile('image');
49	            $hasVideo = $this->hasFile('video');
50	
51	            if ($hasImage && $hasVideo) {
52	                $v->errors()->add('image', 'Provide either an image or a video, not both.');
53	
54	                return;
55	            }
56	
57	            if (! $hasImage && ! $hasVideo) {
58	                $v->errors()->add('image', 'An image or video file is required.');
59	
60	                return;
61	            }
62	
63	            if ($hasVideo && ! config('sidest.video_uploads_enabled', false)) {
64	                $v->errors()->add('video', 'Video uploads are not currently enabled.');
65	            }
66	        });
67	    }
68	
69	    protected function prepareForValidation(): void
70	    {
71	        if (is_string($this->pool ?? null)) {
72	            $this->merge(['pool' => strtolower(trim($this->pool))]);
73	        }
74	    }
75	
76	    public function messages(): array
77	    {
78	        $imageMaxMb = round(((int) config('sidest.image_max_upload_size', 10240)) / 1024, 1);
79	        $videoMaxMb = round(((int) config('sidest.video_max_upload_size', 512000)) / 1024, 0);
80	
81	        return [
82	            'pool.in' => 'Pool must be one of: ' . implode(', ', config('sidest.upload_pools')) . '.',
83	            'image.max' => "Image must be smaller than {$imageMaxMb} MB.",
84	            'image.mimes' => 'Image must be JPEG, PNG, or WebP.',
85	            'image.image' => 'The file must be a valid image.',
86	            'video.max' => "Video must be smaller than {$videoMaxMb} MB.",
87	            'video.mimes' => 'Video must be MP4, MOV, WebM, or AVI.',
88	        ];
89	    }
90	}
