7	// V2: Base form request with shared input sanitization helpers — trim, lowercase, and email normalization.
8	abstract class BaseFormRequest extends FormRequest
9	{
10	    /**
11	     * Authorization is enforced entirely by route middleware (VerifySupabaseJwt,
12	     * LoadCurrentProfessional, staff guards) and resource Policies invoked from
13	     * controllers via `authorizeForUser($pro, ...)`. This method is intentionally
14	     * `final` — Supabase JWT means `Auth::user()` is always null, so any logic
15	     * here would gate against a null user and create a second, inconsistent
16	     * authorization surface. Do NOT override.
17	     */
18	    final public function authorize(): bool
19	    {
20	        return true;
21	    }
22	
23	    /**
24	     * Trim string inputs.
25	     */
26	    protected function trimStrings(array $keys): void
27	    {
28	        $data = [];
29	
30	        foreach ($keys as $key) {
31	            $value = $this->input($key);
32	            if (is_string($value)) {
33	                $data[$key] = trim($value);
34	            }
35	        }
36	
37	        if (! empty($data)) {
38	            $this->merge($data);
39	        }
40	    }
41	
42	    /**
43	     * Lowercase string inputs.
44	     */
45	    protected function lowercaseStrings(array $keys): void
46	    {
47	        $data = [];
48	
49	        foreach ($keys as $key) {
50	            $value = $this->input($key);
51	            if (is_string($value)) {
52	                $data[$key] = strtolower(trim($value));
53	            }
54	        }
55	
56	        if (! empty($data)) {
57	            $this->merge($data);
58	        }
59	    }
60	
61	    /**
62	     * Sanitize email inputs (trim and lowercase).
63	     */
64	    protected function sanitizeEmails(array $keys): void
65	    {
66	        $this->lowercaseStrings($keys);
67	    }
68	
69	    /**
70	     * Canonical phone validation rule — shared `string + max` constraints.
71	     * Callers prepend required/nullable/sometimes for their own semantics:
72	     *   'phone' => ['required', ...$this->phoneRule()]
73	     */
74	    protected function phoneRule(): array
75	    {
76	        return ['string', 'max:50'];
77	    }
78	
79	    /**
80	     * Normalize phone-like inputs to digits and a leading `+` only.
81	     * Strips whitespace, parens, dashes, and any other punctuation. Empty
82	     * results coerce to null so downstream code never has to distinguish
83	     * '' from null. Skips keys that are absent or not strings.
84	     */
85	    protected function normalizePhones(array $keys): void
86	    {
87	        $data = [];
88	
89	        foreach ($keys as $key) {
90	            if (! $this->has($key)) {
91	                continue;
92	            }
93	            $value = $this->input($key);
94	            if (! is_string($value)) {
95	                continue;
96	            }
97	            $normalized = preg_replace('/[^\d+]/', '', trim($value));
98	            $data[$key] = $normalized === '' ? null : $normalized;
99	        }
100	
101	        if (! empty($data)) {
102	            $this->merge($data);
103	        }
104	    }
105	
106	    /**
107	     * Value-level twin of `cleanText`. Strips HTML tags, ASCII control chars,
108	     * and surrounding whitespace from a single string; returns null for empty
109	     * results AND for non-string input. Lifted out of cleanText so traits
110	     * (ValidatesProfessionalAbout) and nested-array loops (settings.*) can
111	     * share the exact same transform without re-implementing it.
112	     */
113	    protected static function cleanString(?string $value): ?string
114	    {
115	        if (! is_string($value)) {
116	            return null;
117	        }
118	        // strip_tags() leaves content inside <script>/<style> blocks — remove those blocks entirely first.
119	        $noScripts = preg_replace('/<(script|style)\b[^>]*>.*?<\/\1>/is', '', $value) ?? $value;
120	        $stripped = preg_replace('/[\x00-\x1F\x7F]/', '', strip_tags($noScripts));
121	        $cleaned = trim((string) $stripped);
122	
123	        return $cleaned === '' ? null : $cleaned;
124	    }
125	
126	    /**
127	     * Clean user-authored text inputs: strip HTML tags, ASCII control chars,
128	     * and surrounding whitespace; coerce empty results to null. Defense-in-depth
129	     * against stored XSS for fields that are echoed by the frontend. Skips keys
130	     * that are absent or not strings.
131	     */
132	    protected function cleanText(array $keys): void
133	    {
134	        $data = [];
135	
136	        foreach ($keys as $key) {
137	            if (! $this->has($key)) {
138	                continue;
139	            }
140	            $value = $this->input($key);
141	            if (! is_string($value)) {
142	                continue;
143	            }
144	            $data[$key] = static::cleanString($value);
145	        }
146	
147	        if (! empty($data)) {
148	            $this->merge($data);
149	        }
150	    }
151	
152	    /**
153	     * Lowercase email-like inputs and coerce empty strings to null. Use this
154	     * for fields backed by a unique index where the difference between '' and
155	     * null matters (e.g. professionals.primary_email). For looser semantics
156	     * use `sanitizeEmails`.
157	     */
158	    protected function lowercaseEmails(array $keys): void
159	    {
160	        $data = [];
161	
162	        foreach ($keys as $key) {
163	            if (! $this->has($key)) {
164	                continue;
165	            }
166	            $value = $this->input($key);
167	            if (! is_string($value)) {
168	                continue;
169	            }
170	            $normalized = mb_strtolower(trim($value));
171	            $data[$key] = ($normalized === '') ? null : $normalized;
172	        }
173	
174	        if (! empty($data)) {
175	            $this->merge($data);
176	        }
177	    }
178	}
