5	// V2: Shared validation + normalization for the professional "about" payload
6	// (credentials + experience). Used by UpdateProfessionalRequest (self-serve)
7	// and StaffUpdateProfessionalRequest so both endpoints enforce identical shape.
8	trait ValidatesProfessionalAbout
9	{
10	    /**
11	     * Merge these into the rules() array of the consuming Form Request.
12	     *
13	     * @return array<string, array<int, mixed>>
14	     */
15	    protected function aboutRules(): array
16	    {
17	        $currentYear = (int) date('Y');
18	
19	        return [
20	            'about' => ['sometimes', 'array'],
21	            'about.credentials' => ['sometimes', 'array', 'max:5'],
22	            'about.credentials.*' => ['array:title,issuer,year'],
23	            'about.credentials.*.title' => ['required', 'string', 'max:120'],
24	            'about.credentials.*.issuer' => ['sometimes', 'nullable', 'string', 'max:120'],
25	            'about.credentials.*.year' => ['sometimes', 'nullable', 'integer', 'min:1900', 'max:'.($currentYear + 1)],
26	
27	            'about.experience' => ['sometimes', 'array', 'max:5'],
28	            'about.experience.*' => ['array:role,place,start,end,description'],
29	            'about.experience.*.role' => ['required', 'string', 'max:120'],
30	            'about.experience.*.place' => ['sometimes', 'nullable', 'string', 'max:120'],
31	            'about.experience.*.start' => ['sometimes', 'nullable', 'string', 'date_format:Y-m'],
32	            'about.experience.*.end' => ['sometimes', 'nullable', 'string', 'date_format:Y-m'],
33	            'about.experience.*.description' => ['sometimes', 'nullable', 'string', 'max:1000'],
34	        ];
35	    }
36	
37	    /**
38	     * Call from the Form Request's prepareForValidation() before any other merges.
39	     * Strips HTML from free-text fields and coerces empty strings to null so the
40	     * JSONB payload stays clean.
41	     */
42	    protected function normalizeAboutPayload(): void
43	    {
44	        $about = $this->input('about');
45	        if (! is_array($about)) {
46	            return;
47	        }
48	
49	        if (isset($about['credentials']) && is_array($about['credentials'])) {
50	            foreach ($about['credentials'] as $i => $row) {
51	                if (! is_array($row)) {
52	                    continue;
53	                }
54	                $about['credentials'][$i]['title'] = $this->cleanStringOrNull($row['title'] ?? null);
55	                $about['credentials'][$i]['issuer'] = $this->cleanStringOrNull($row['issuer'] ?? null);
56	                // year is left as-is; validator coerces / rejects
57	            }
58	        }
59	
60	        if (isset($about['experience']) && is_array($about['experience'])) {
61	            foreach ($about['experience'] as $i => $row) {
62	                if (! is_array($row)) {
63	                    continue;
64	                }
65	                $about['experience'][$i]['role'] = $this->cleanStringOrNull($row['role'] ?? null);
66	                $about['experience'][$i]['place'] = $this->cleanStringOrNull($row['place'] ?? null);
67	                $about['experience'][$i]['description'] = $this->cleanStringOrNull($row['description'] ?? null);
68	                // start / end are kept as supplied; validator enforces Y-m format
69	                if (($about['experience'][$i]['start'] ?? null) === '') {
70	                    $about['experience'][$i]['start'] = null;
71	                }
72	                if (($about['experience'][$i]['end'] ?? null) === '') {
73	                    $about['experience'][$i]['end'] = null;
74	                }
75	            }
76	        }
77	
78	        $this->merge(['about' => $about]);
79	    }
80	
81	    /**
82	     * Cross-field rule: each experience entry's `end` must be >= `start` when both set.
83	     * Call from withValidator() in the Form Request.
84	     */
85	    protected function validateExperienceDateOrder(\Illuminate\Validation\Validator $validator): void
86	    {
87	        $experience = (array) data_get($this->all(), 'about.experience', []);
88	        foreach ($experience as $i => $row) {
89	            $start = $row['start'] ?? null;
90	            $end = $row['end'] ?? null;
91	            if (is_string($start) && is_string($end) && $end < $start) {
92	                $validator->errors()->add(
93	                    "about.experience.$i.end",
94	                    'The end month must be on or after the start month.'
95	                );
96	            }
97	        }
98	    }
99	
100	    /**
101	     * Delegates to BaseFormRequest::cleanString — kept here as a thin alias so
102	     * the trait's nested-walks (credentials.*, experience.*) can stay readable.
103	     * The trait is only ever used by classes that extend BaseFormRequest, so
104	     * static::cleanString resolves through the consuming class.
105	     */
106	    private function cleanStringOrNull(mixed $value): ?string
107	    {
108	        return static::cleanString(is_string($value) ? $value : null);
109	    }
110	}
